struct Badge: View {
  var body: some View {
    Text("Sale")
      .padding(8)                      // proposes (offered size - 16) to the Text
      .background(.pink)               // sizes itself around the padded text
      .frame(width: 200, height: 60)   // a NEW parent 200x60; the badge centres inside it
  }
}

// .frame never resizes the child. It proposes a size and positions whatever comes back.
Text(longString).frame(width: 100)           // Text wraps into 100pt
Image("logo").frame(width: 100)              // fixed-size image is centred, not scaled
Image("logo").resizable().frame(width: 100)  // resizable accepts any proposal

// A nil proposal asks "what is your ideal size?" — that is what fixedSize sends
Text(paragraph)
  .fixedSize(horizontal: false, vertical: true)   // stop the vertical truncation

// Greedy views take everything offered
HStack {
  Text("Left")
  Spacer()        // handed .infinity, so it absorbs the slack
  Text("Right")
}

// GeometryReader returns the whole proposal, which is why it expands
GeometryReader { proxy in
  Chart(data).frame(width: proxy.size.width * 0.5)
}
.frame(height: 200)   // bound it, or it eats the enclosing stack

// When two children fight over the space, break the tie explicitly
HStack {
  Text(title).layoutPriority(1)
  Text(subtitle)
}

struct Header: View {
  let isEditing: Bool

  var body: some View {          // body is @ViewBuilder, so several statements are allowed
    HStack {
      Text("Inbox").font(.headline)
      Spacer()
      if isEditing { Button("Done") {} } else { Button("Edit") {} }
    }
  }
}
// The three statements become TupleView<(Text, Spacer, _ConditionalContent<Button, Button>)>
// and the if/else branches are two different types — switching them resets any @State inside.

// Your own container that takes a builder
struct Card<Content: View>: View {
  @ViewBuilder var content: Content

  var body: some View {
    VStack(alignment: .leading, spacing: 8) { content }
      .padding()
      .background(.thinMaterial, in: .rect(cornerRadius: 12))
  }
}

// A builder-annotated helper keeps the concrete type instead of erasing it
@ViewBuilder
private var status: some View {
  switch state {
  case .loading: ProgressView()
  case .failed:  Label("Failed", systemImage: "xmark.octagon")
  case .ready:   EmptyView()
  }
}

// AnyView throws the type away, so SwiftUI can no longer diff these structurally
private var erased: AnyView {   // avoid
  state == .loading ? AnyView(ProgressView()) : AnyView(Text("Ready"))
}

// A loop needs ForEach: the builder cannot collect statements out of a `for`
ForEach(items) { item in Row(item: item) }

struct InboxView: View {
  @State private var isShowingSettings = false
  @State private var editing: Message?          // nil means no sheet
  @State private var pendingDelete: Message?
  @State private var isConfirmingDelete = false

  var body: some View {
    List(messages) { message in
      Row(message: message).onTapGesture { editing = message }   // set the item, not a Bool
    }
    .toolbar { Button("Settings") { isShowingSettings = true } }

    .sheet(isPresented: $isShowingSettings) {
      SettingsView()
        .presentationDetents([.medium, .large])
        .presentationDragIndicator(.visible)
    }

    // The item form hands the value to the builder, so it can never show stale data
    .sheet(item: $editing) { message in
      EditorView(message: message)
    }

    .confirmationDialog("Delete message?", isPresented: $isConfirmingDelete,
                        presenting: pendingDelete) { message in
      Button("Delete", role: .destructive) { delete(message) }
      Button("Cancel", role: .cancel) {}
    }
  }
}

// The presented view dismisses itself without knowing who presented it
struct SettingsView: View {
  @Environment(\.dismiss) private var dismiss

  var body: some View {
    Button("Close") { dismiss() }
  }
}

struct Panel: View {
  @State private var isExpanded = false
  @State private var count = 0

  var body: some View {
    VStack {
      Text("\(count)")
        .contentTransition(.numericText())   // digits roll instead of cross-fading
        .animation(.snappy, value: count)    // scoped: this view, this value only

      if isExpanded {
        Details()
          .transition(.move(edge: .bottom).combined(with: .opacity))
      }

      Button("Toggle") {
        withAnimation(.bouncy) { isExpanded.toggle() }   // animates the insertion above
      }
    }
  }
}

