// ScrollView + LazyVStack: arbitrary layout, no cell chrome, rows built as they approach
ScrollView {
  LazyVStack(alignment: .leading, spacing: 16, pinnedViews: [.sectionHeaders]) {
    ForEach(sections) { section in
      Section {
        ForEach(section.items) { Card(item: $0) }
      } header: {
        SectionHeader(section)
      }
    }
  }
  .scrollTargetLayout()
}
.scrollPosition(id: $topItemID)
.contentMargins(.horizontal, 16, for: .scrollContent)

