struct MessageRow: View {
  let message: Message
  @Environment(\.dynamicTypeSize) private var typeSize

  var body: some View {
    let layout = typeSize.isAccessibilitySize
      ? AnyLayout(VStackLayout(alignment: .leading))   // stack vertically at huge text sizes
      : AnyLayout(HStackLayout(alignment: .center))

    layout {
      Image(systemName: message.icon)
        .accessibilityHidden(true)                     // decorative, not its own stop
      VStack(alignment: .leading) {
        Text(message.sender).font(.headline)           // semantic fonts scale for free
        Text(message.preview).font(.subheadline)
      }
      Spacer()
      if message.isUnread { Circle().fill(.blue).frame(width: 8, height: 8) }
    }
    .accessibilityElement(children: .combine)          // one swipe stop instead of four
    .accessibilityLabel(message.isUnread ? "Unread, \(message.sender)" : message.sender)
    .accessibilityHint("Opens the conversation")
    .accessibilityAddTraits(.isButton)
  }
}

